using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics, from algebra to statistics." },
        new() { Code = "ENG", Name = "English", Description = "Literature, writing, and language studies." },
        new() { Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Code = "HIST", Name = "History", Description = "Exploration of past events, societies, and civilizations." },
    ];

    private static readonly List<Course> Courses =
    [
        new() { Id = 1, Code = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published extensively on pedagogy in computing education.", DepartmentCode = "CS", IsFeatured = true },
        new() { Id = 2, Code = "CS201", Title = "Data Structures & Algorithms", Description = "A deep dive into fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming).", Credits = 4, Schedule = "TTh 10:30–11:45 AM", InstructorName = "Dr. James Okafor", InstructorBio = "Dr. Okafor's research focuses on efficient algorithms for large-scale data processing. He holds a PhD from MIT.", DepartmentCode = "CS", IsFeatured = true },
        new() { Id = 3, Code = "CS350", Title = "Software Engineering", Description = "Principles of software development including requirements analysis, design patterns, testing, and agile methodologies.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", InstructorName = "Prof. Maria Lopez", InstructorBio = "Prof. Lopez spent 10 years in industry at major tech companies before joining academia. She specializes in DevOps and CI/CD practices.", DepartmentCode = "CS", IsFeatured = false },
        new() { Id = 4, Code = "MATH101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator who has taught calculus for over 20 years.", DepartmentCode = "MATH", IsFeatured = true },
        new() { Id = 5, Code = "MATH202", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, and eigenvalues.", Credits = 3, Schedule = "TTh 2:00–3:15 PM", InstructorName = "Dr. Anika Patel", InstructorBio = "Dr. Patel's research is in numerical linear algebra and its applications to machine learning.", DepartmentCode = "MATH", IsFeatured = false },
        new() { Id = 6, Code = "MATH310", Title = "Probability & Statistics", Description = "Introduction to probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator who has taught calculus for over 20 years.", DepartmentCode = "MATH", IsFeatured = false },
        new() { Id = 7, Code = "ENG101", Title = "College Writing", Description = "Develop critical thinking and clear writing through essays, research papers, and peer workshops.", Credits = 3, Schedule = "TTh 9:00–10:15 AM", InstructorName = "Prof. David Wright", InstructorBio = "Prof. Wright is a published novelist and essayist who has taught writing at the university level for 12 years.", DepartmentCode = "ENG", IsFeatured = false },
        new() { Id = 8, Code = "ENG250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, including poetry, fiction, and drama.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", InstructorName = "Dr. Lisa Hernandez", InstructorBio = "Dr. Hernandez specializes in 20th-century American fiction and has authored three books on the subject.", DepartmentCode = "ENG", IsFeatured = true },
        new() { Id = 9, Code = "PHYS101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", Credits = 4, Schedule = "MWF 10:00–10:50 AM, Lab: F 2:00–4:50 PM", InstructorName = "Dr. Thomas Müller", InstructorBio = "Dr. Müller is an experimental physicist whose research involves particle detectors at CERN.", DepartmentCode = "PHYS", IsFeatured = false },
        new() { Id = 10, Code = "PHYS202", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "TTh 1:00–2:15 PM, Lab: W 3:00–5:50 PM", InstructorName = "Dr. Thomas Müller", InstructorBio = "Dr. Müller is an experimental physicist whose research involves particle detectors at CERN.", DepartmentCode = "PHYS", IsFeatured = false },
        new() { Id = 11, Code = "HIST101", Title = "World History to 1500", Description = "A survey of major civilizations, cultures, and events from antiquity through the late medieval period.", Credits = 3, Schedule = "TTh 11:00 AM–12:15 PM", InstructorName = "Dr. Eleanor Shaw", InstructorBio = "Dr. Shaw is a medieval historian with expertise in cross-cultural exchange along the Silk Road.", DepartmentCode = "HIST", IsFeatured = false },
        new() { Id = 12, Code = "HIST205", Title = "Modern European History", Description = "Europe from the Enlightenment to the present: revolutions, wars, and the formation of the EU.", Credits = 3, Schedule = "MWF 3:00–3:50 PM", InstructorName = "Dr. Eleanor Shaw", InstructorBio = "Dr. Shaw is a medieval historian with expertise in cross-cultural exchange along the Silk Road.", DepartmentCode = "HIST", IsFeatured = true },
    ];

    public List<Department> GetDepartments() => Departments;

    public Department? GetDepartment(string code) =>
        Departments.FirstOrDefault(d => d.Code.Equals(code, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetCourses(string? search = null, string? departmentCode = null)
    {
        var query = Courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentCode))
        {
            query = query.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.Code).ToList();
    }

    public List<Course> GetFeaturedCourses() =>
        Courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) =>
        Courses.FirstOrDefault(c => c.Id == id);
}

