@page "/"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<h1>University Course Catalog</h1>
<p class="lead">Explore our departments and courses for the upcoming semester.</p>

<section class="mb-5">
    <h2>Featured Courses</h2>
    <div class="row">
        @foreach (var course in featuredCourses)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@course.Code — @course.Title</h5>
                        <p class="card-text text-muted">@course.Credits credits · @course.InstructorName</p>
                        <p class="card-text">@Truncate(course.Description, 100)</p>
                    </div>
                    <div class="card-footer bg-transparent">
                        <a href="courses/@course.Id" class="btn btn-primary btn-sm">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

<section>
    <h2>Departments</h2>
    <div class="list-group">
        @foreach (var dept in departments)
        {
            <a href="courses?department=@dept.Code" class="list-group-item list-group-item-action">
                <strong>@dept.Name (@dept.Code)</strong>
                <span class="text-muted ms-2">@dept.Description</span>
            </a>
        }
    </div>
</section>

@code {
    private List<UniversityCourseCatalog.Models.Course> featuredCourses = [];
    private List<UniversityCourseCatalog.Models.Department> departments = [];

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetFeaturedCourses();
        departments = CatalogService.GetDepartments();
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

